// forbiddenImportPrefixes are module paths the customer-facing entire-ci plugin
// must never pull into its build graph.
//
//   - entire.io/... is the PRIVATE entiredb module — home of the ci-webhooks
//     leaf admin-API client, the platform-admin ops-token minting path, and the
//     AES cipher for Buildkite org tokens. If any of it reached this graph the
//     plugin could, in principle, talk to the leaf admin API or mint an
//     ops-token, which is exactly what must be impossible.
//   - github.com/entireio/cli is the customer CLI. We deliberately VENDOR the
//     small login-contract packages (contexts, tokenstore) rather than import
//     the cli module, so the plugin's graph stays minimal and independent.
//
// Keeping both out of the graph makes "this tool can only reach entire-core's
// SpiceDB-authorized /api/v1 with the user's login JWT" a mechanical fact.
// See ADR 20260717-entire-ci-pluggable-client.
var forbiddenImportPrefixes = []string{
	"entire.io/",
	"github.com/entireio/cli/",
}

// TestNoForbiddenImports fails if any package in the module's transitive build
// graph is (or lives under) a forbidden module. This is the customer-safe
// boundary gate — it must run in CI.
func TestNoForbiddenImports(t *testing.T) {
	out, err := exec.Command("go", "list", "-deps", "github.com/entireio/entire-ci/...").Output()
	if err != nil {
		t.Fatalf("go list -deps: %v", err)
	}
	for _, pkg := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		pkg = strings.TrimSpace(pkg)
		if pkg == "" {
			continue
		}
		for _, bad := range forbiddenImportPrefixes {
			if pkg == strings.TrimSuffix(bad, "/") || strings.HasPrefix(pkg, bad) {
				t.Errorf("forbidden import in build graph: %q (matches %q) — the customer plugin must never depend on it; see ADR 20260717-entire-ci-pluggable-client", pkg, bad)
			}
		}
	}
}

