package corecli

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
)

// Client talks to entire-core's /api/v1 as the logged-in user. Its base URL
// already includes the /api/v1 prefix; call paths are relative to it.
type Client struct {
	baseURL *url.URL
	hc      *http.Client
}

// New builds a Client for the active login, honoring the --core-url and
// --context overrides (either may be "").
func New(coreURLOverride, contextOverride string) (*Client, error) {
	base, hc, err := resolveLogin(coreURLOverride, contextOverride)
	if err != nil {
		return nil, err
	}
	u, err := url.Parse(base)
	if err != nil {
		return nil, fmt.Errorf("parse core URL %q: %w", base, err)
	}
	return &Client{baseURL: u, hc: hc}, nil
}

// NewWithHTTP builds a Client against an explicit base URL and *http.Client.
// It is for tests (pointing at an httptest server); production code uses New.
func NewWithHTTP(baseURL string, hc *http.Client) (*Client, error) {
	u, err := url.Parse(baseURL)
	if err != nil {
		return nil, fmt.Errorf("parse base URL %q: %w", baseURL, err)
	}
	return &Client{baseURL: u, hc: hc}, nil
}

// GetJSON issues a GET to path (relative to the /api/v1 base) and decodes a 2xx
// JSON body into dst. A non-2xx response becomes an *APIStatusError carrying the
// server's RFC 7807 problem detail.
func (c *Client) GetJSON(ctx context.Context, path string, query url.Values, dst any) error {
	req, err := c.newRequest(ctx, http.MethodGet, path, query, nil)
	if err != nil {
		return err
	}
	return c.do(req, dst)
}

// PostJSON issues a POST with a JSON body and returns the response status code
// (so callers can tell 201-created from 200-updated). dst may be nil.
func (c *Client) PostJSON(ctx context.Context, path string, body, dst any) (int, error) {
	return c.sendBody(ctx, http.MethodPost, path, body, dst)
}

// PatchJSON issues a PATCH with a JSON body and returns the response status
// code. dst may be nil.
func (c *Client) PatchJSON(ctx context.Context, path string, body, dst any) (int, error) {
	return c.sendBody(ctx, http.MethodPatch, path, body, dst)
}

// DeleteJSON issues a DELETE (optionally with query params, e.g. keep_identity) and
// returns nil on any 2xx. A non-2xx becomes an *APIStatusError.
func (c *Client) DeleteJSON(ctx context.Context, path string, query url.Values) error {
	req, err := c.newRequest(ctx, http.MethodDelete, path, query, nil)
	if err != nil {
		return err
	}
	return c.do(req, nil)
}

// PutJSON issues a bodyless PUT and decodes a 2xx JSON body into dst. Bodyless on
// purpose: the routes that use it take every argument in the path, so there is
// nothing to send — and an empty JSON body would be a field the server has to
// choose whether to reject.
func (c *Client) PutJSON(ctx context.Context, path string, dst any) error {
	req, err := c.newRequest(ctx, http.MethodPut, path, nil, nil)
	if err != nil {
		return err
	}
	return c.do(req, dst)
}

func (c *Client) sendBody(ctx context.Context, method, path string, body, dst any) (int, error) {
	buf, err := json.Marshal(body)
	if err != nil {
		return 0, fmt.Errorf("encode request body: %w", err)
	}
	req, err := c.newRequest(ctx, method, path, nil, bytes.NewReader(buf))
	if err != nil {
		return 0, err
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := c.hc.Do(req)
	if err != nil {
		return 0, fmt.Errorf("do request: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return resp.StatusCode, statusCodeError(resp)
	}
	if dst != nil {
		if err := json.NewDecoder(resp.Body).Decode(dst); err != nil {
			return resp.StatusCode, fmt.Errorf("decode response: %w", err)
		}
	}
	return resp.StatusCode, nil
}

func (c *Client) newRequest(ctx context.Context, method, path string, query url.Values, body io.Reader) (*http.Request, error) {
	u := c.baseURL.JoinPath(path)
	if len(query) > 0 {
		u.RawQuery = query.Encode()
	}
	if body == nil {
		body = http.NoBody
	}
	req, err := http.NewRequestWithContext(ctx, method, u.String(), body)
	if err != nil {
		return nil, fmt.Errorf("build request: %w", err)
	}
	req.Header.Set("Accept", "application/json")
	return req, nil
}

func (c *Client) do(req *http.Request, dst any) error {
	resp, err := c.hc.Do(req)
	if err != nil {
		return fmt.Errorf("do request: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return statusCodeError(resp)
	}
	if dst != nil {
		if err := json.NewDecoder(resp.Body).Decode(dst); err != nil {
			return fmt.Errorf("decode response: %w", err)
		}
	}
	return nil
}

// ProblemDetail is the RFC 7807 problem+json body entire-core returns on error.
//
// The cross-jurisdiction 421 is also problem+json but carries its own fields
// instead of the standard ones: Message (`error`), HomeCoreURL and Jurisdiction
// name the core that actually serves the repo. See RedirectTarget.
type ProblemDetail struct {
	Type     string               `json:"type,omitempty"`
	Title    string               `json:"title,omitempty"`
	Status   int                  `json:"status,omitempty"`
	Detail   string               `json:"detail,omitempty"`
	Instance string               `json:"instance,omitempty"`
	Errors   []ProblemErrorDetail `json:"errors,omitempty"`

	// 421 cross-jurisdiction redirect fields.
	Message      string `json:"error,omitempty"`
	HomeCoreURL  string `json:"home_core_url,omitempty"`
	Jurisdiction string `json:"jurisdiction,omitempty"`
}

// ProblemErrorDetail is one field-level validation error within a ProblemDetail.
type ProblemErrorDetail struct {
	Message  string `json:"message,omitempty"`
	Location string `json:"location,omitempty"`
}

// APIStatusError is a non-2xx response from entire-core.
type APIStatusError struct {
	StatusCode int
	Problem    ProblemDetail
}

func (e *APIStatusError) Error() string {
	switch {
	case e.Problem.Detail != "":
		return e.Problem.Detail
	case e.Problem.Title != "":
		return e.Problem.Title
	case e.Problem.Message != "": // 421 redirect body uses `error`
		return e.Problem.Message
	default:
		return fmt.Sprintf("control-plane request failed with status %d", e.StatusCode)
	}
}

// statusCodeError turns a non-2xx response into an *APIStatusError, decoding the
// RFC 7807 body when present (best-effort — a missing/non-JSON body yields a
// status-only error).
func statusCodeError(resp *http.Response) error {
	e := &APIStatusError{StatusCode: resp.StatusCode}
	if body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20)); err == nil && len(body) > 0 {
		_ = json.Unmarshal(body, &e.Problem) //nolint:errcheck // best-effort problem decode
	}
	return e
}

// APIError reports the server's problem message for err, or "" if err isn't an
// *APIStatusError. Callers surface this instead of the transport-wrapped string.
func APIError(err error) string {
	var se *APIStatusError
	if !errors.As(err, &se) {
		return ""
	}
	return strings.TrimSpace(se.Error())
}

// IsNotFound reports whether err is a control-plane 404.
func IsNotFound(err error) bool {
	var se *APIStatusError
	return errors.As(err, &se) && se.StatusCode == http.StatusNotFound
}

// HasProblemDetail reports whether err carries a server-supplied RFC 7807
// message. False means the response had no problem body — a router-level status
// rather than a handler's answer.
func HasProblemDetail(err error) bool {
	var se *APIStatusError
	if !errors.As(err, &se) {
		return false
	}
	return se.Problem.Detail != "" || se.Problem.Title != ""
}

// IsUnauthorized reports whether err is a control-plane 401. This client never
// refreshes the stored token (see resolveLogin), so in normal use a 401 means the
// login expired — which is why the caller turns it into a re-login hint rather
// than surfacing the bare status.
func IsUnauthorized(err error) bool {
	var se *APIStatusError
	return errors.As(err, &se) && se.StatusCode == http.StatusUnauthorized
}

// IsMisdirected reports whether err is a control-plane 421 — the repo's CI is
// served by a different jurisdiction's core. RedirectTarget names which.
func IsMisdirected(err error) bool {
	var se *APIStatusError
	return errors.As(err, &se) && se.StatusCode == http.StatusMisdirectedRequest
}

// RedirectTarget returns the home-core URL and jurisdiction from a 421 redirect
// body, and whether err was a 421 carrying a usable home-core URL. The client
// does not follow the redirect itself; the caller tells the user to retry with
// --core-url.
func RedirectTarget(err error) (homeCoreURL, jurisdiction string, ok bool) {
	var se *APIStatusError
	if !errors.As(err, &se) || se.StatusCode != http.StatusMisdirectedRequest {
		return "", "", false
	}
	return se.Problem.HomeCoreURL, se.Problem.Jurisdiction, se.Problem.HomeCoreURL != ""
}
