// Package tokenstore provides a pluggable credential store shared by the
// Entire CLIs.
//
// By default it delegates to the OS keyring (macOS Keychain, Linux Secret
// Service, etc.). Set ENTIRE_TOKEN_STORE=file to use a JSON file instead,
// which is useful in CI environments that lack a keyring daemon.
//
// When using the file backend the tokens are stored in
// $ENTIRE_TOKEN_STORE_PATH (default: tokens.json in the per-user config
// directory — see internal/clientcreds/userdirs).
//
// Service-name conventions:
//   - "entire:<cluster-host>"        — entiredb cluster login tokens
//   - "entire-core:<core-base-url>"  — entire-core control-plane tokens
//   - "<service>:refresh"            — refresh-token entry paired with the
//     corresponding access-token service
//
// Vendored from the public CLI's internal/entireclient/tokenstore so the
// keyring service names stay byte-compatible with `entire login` (the test-only
// testdirs redirection and the procsignal interrupt marker are dropped — a
// plugin needs neither). See ADR 20260717-entire-ci-pluggable-client.
package tokenstore

import (
	"os"
	"path/filepath"
	"strings"
	"sync"

	"github.com/zalando/go-keyring"

	"github.com/entireio/entire-ci/internal/clientcreds/userdirs"
)

// ErrNotFound is returned when a credential is not present in the store.
var ErrNotFound = keyring.ErrNotFound

// Keyring service-name prefixes. Tokens are filed under whichever issuer
// vouched for them, so a JWT obtained via an entire-core login flow lives
// at "entire-core:<base-url>" regardless of which CLI wrote it.
const (
	ClusterKeyringPrefix = "entire:"      // entiredb cluster-issued tokens
	CoreKeyringPrefix    = "entire-core:" // entire-core control-plane tokens
)

// ClusterKeyringService returns the service name for tokens issued by an
// entiredb cluster. host is typically the cluster's entry domain.
func ClusterKeyringService(host string) string {
	return ClusterKeyringPrefix + host
}

// CoreKeyringService returns the service name for tokens issued by
// entire-core. coreURL is the base URL of the issuer; trailing slashes
// are normalized away so callers don't have to.
func CoreKeyringService(coreURL string) string {
	return CoreKeyringPrefix + strings.TrimRight(coreURL, "/")
}

// RefreshService returns the paired refresh-token service name for an
// access-token service, following the "<service>:refresh" convention.
func RefreshService(service string) string {
	return service + ":refresh"
}

// KeyringServiceForIssuerKey infers the right service prefix from a
// raw issuer key (entire-core URL or entiredb cluster host). URL-shaped
// keys are treated as entire-core issuers; bare hostnames as cluster issuers.
func KeyringServiceForIssuerKey(key string) string {
	if strings.HasPrefix(key, "http://") || strings.HasPrefix(key, "https://") {
		return CoreKeyringService(key)
	}
	return ClusterKeyringService(key)
}

// backendMu guards `resolved` and `backend`.
var (
	backendMu sync.Mutex
	resolved  bool
	backend   store
)

type store interface {
	Get(service, user string) (string, error)
	Set(service, user, password string) error
	Delete(service, user string) error
}

func currentBackend() store {
	backendMu.Lock()
	defer backendMu.Unlock()
	if !resolved {
		backend = resolveBackendLocked()
		resolved = true
	}
	return backend
}

func resolveBackendLocked() store {
	if os.Getenv("ENTIRE_TOKEN_STORE") == "file" {
		path := os.Getenv("ENTIRE_TOKEN_STORE_PATH")
		if path == "" {
			path = filepath.Join(userdirs.Config(), "tokens.json")
		}
		return &fileStore{path: path}
	}
	return keyringStore{}
}

// Get retrieves a credential.
func Get(service, user string) (string, error) {
	//nolint:wrapcheck // thin wrapper, callers handle errors
	return currentBackend().Get(service, user)
}

// Set stores a credential.
func Set(service, user, password string) error {
	//nolint:wrapcheck // thin wrapper, callers handle errors
	return currentBackend().Set(service, user, password)
}

// Delete removes a credential.
func Delete(service, user string) error {
	//nolint:wrapcheck // thin wrapper, callers handle errors
	return currentBackend().Delete(service, user)
}

// keyringStore delegates to the OS keyring. Every call is bounded by
// callKeyringWithTimeout: the underlying provider can block indefinitely when
// no daemon is reachable, and an unbounded keyring call freezes the whole CLI.
type keyringStore struct{}

func (keyringStore) Get(service, user string) (string, error) {
	return callKeyringWithTimeout("get", func() (string, error) {
		return keyring.Get(service, user)
	})
}

func (keyringStore) Set(service, user, password string) error {
	_, err := callKeyringWithTimeout("set", func() (string, error) {
		return "", keyring.Set(service, user, password)
	})
	return err
}

func (keyringStore) Delete(service, user string) error {
	_, err := callKeyringWithTimeout("delete", func() (string, error) {
		return "", keyring.Delete(service, user)
	})
	return err
}
package tokenstore

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"runtime"
	"time"
)

// defaultKeyringTimeout caps how long every OS keyring call may take. The
// underlying keyring API can block indefinitely when no provider is reachable
// — a headless SSH/container/WSL session, a suppressed Keychain prompt, a stuck
// Credential Manager — and that freezes the CLI. 5s is comfortably longer than
// any healthy round-trip while still surfacing the hang quickly.
const defaultKeyringTimeout = 5 * time.Second

// keyringTimeoutEnvVar overrides defaultKeyringTimeout. Accepts any
// time.ParseDuration string; invalid or non-positive values fall back to the
// default.
const keyringTimeoutEnvVar = "ENTIRE_KEYRING_TIMEOUT"

func keyringTimeout() time.Duration {
	v := os.Getenv(keyringTimeoutEnvVar)
	if v == "" {
		return defaultKeyringTimeout
	}
	d, err := time.ParseDuration(v)
	if err != nil || d <= 0 {
		return defaultKeyringTimeout
	}
	return d
}

// callKeyringWithTimeout runs fn in a goroutine and returns its result, or a
// descriptive error if the configured keyring timeout elapses or the user
// interrupts (Ctrl-C) first. The goroutine continues running — a blocked D-Bus
// syscall / Keychain subprocess can't be cancelled from Go — and its eventual
// result is discarded. fn's own error (including ErrNotFound) propagates
// unchanged on the fast path; only the timeout and interrupt branches wrap.
func callKeyringWithTimeout(op string, fn func() (string, error)) (string, error) {
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, os.Interrupt)
	defer signal.Stop(sigCh)
	return callKeyringWithInterrupt(op, keyringTimeout(), fn, sigCh)
}

// callKeyringWithInterrupt is the testable core of callKeyringWithTimeout: the
// interrupt source is injected so tests can exercise the Ctrl-C branch without
// sending real signals to the test process.
func callKeyringWithInterrupt(op string, timeout time.Duration, fn func() (string, error), interrupt <-chan os.Signal) (string, error) {
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	type result struct {
		val string
		err error
	}
	ch := make(chan result, 1)
	go func() {
		v, err := fn()
		ch <- result{val: v, err: err}
	}()
	select {
	case r := <-ch:
		return r.val, r.err
	case <-interrupt:
		// Wrap context.Canceled so the abort flows into the CLI's silent
		// "user aborted" exit path rather than printing as a keyring failure.
		return "", fmt.Errorf("%s interrupted: %w", op, context.Canceled)
	case <-ctx.Done():
		return "", fmt.Errorf(
			"%s timed out: OS keyring (%s) appears unavailable; set %s to a longer duration to wait further: %w",
			op, keyringProviderName(), keyringTimeoutEnvVar, ctx.Err(),
		)
	}
}

// keyringProviderName returns the human name of the OS keyring backend for the
// current platform, so the timeout error can point the user at the specific
// service that's likely stuck.
func keyringProviderName() string {
	switch runtime.GOOS {
	case "darwin":
		return "macOS Keychain"
	case "windows":
		return "Windows Credential Manager"
	case "linux", "freebsd", "openbsd", "netbsd", "dragonfly":
		return "Secret Service (D-Bus)"
	default:
		return "OS keyring"
	}
}
package tokenstore

import (
	"fmt"
	"strings"
	"time"
)

// TokenExpirationSeparator separates the token from its expiration timestamp.
// Format: "token|expires_at_unix"
const TokenExpirationSeparator = "|"

// TokenExpirationBuffer is how long before expiration we should refresh.
const TokenExpirationBuffer = 5 * time.Minute

// DecodeTokenWithExpiration decodes a token that may have an expiration
// timestamp. Returns the token and expiration time. If no expiration is
// encoded, returns the token as-is and a zero time.
func DecodeTokenWithExpiration(encoded string) (token string, expiresAt time.Time) {
	idx := strings.LastIndex(encoded, TokenExpirationSeparator)
	if idx == -1 {
		return encoded, time.Time{}
	}

	token = encoded[:idx]
	var expiresAtUnix int64
	if _, err := fmt.Sscanf(encoded[idx+1:], "%d", &expiresAtUnix); err != nil {
		return encoded, time.Time{}
	}
	return token, time.Unix(expiresAtUnix, 0)
}

// IsTokenExpiredOrExpiring checks if a token is expired or will expire soon.
// A zero expiresAt is treated as "unknown, assume expired".
func IsTokenExpiredOrExpiring(expiresAt time.Time) bool {
	if expiresAt.IsZero() {
		return true
	}
	return time.Now().Add(TokenExpirationBuffer).After(expiresAt)
}
package tokenstore

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/gofrs/flock"
)

// fileStore persists credentials as a JSON file on disk.
// The file format is: { "service": { "user": "password" } }
type fileStore struct {
	path string
	mu   sync.Mutex
}

// withFileLock runs fn while holding an exclusive flock on f.path + ".lock".
// The lock coordinates across processes; the in-process mu handles goroutines.
func (f *fileStore) withFileLock(fn func() error) error {
	if err := os.MkdirAll(filepath.Dir(f.path), 0700); err != nil {
		return fmt.Errorf("creating token store directory: %w", err)
	}

	fl := flock.New(f.path + ".lock")
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	locked, err := fl.TryLockContext(ctx, 50*time.Millisecond)
	if err != nil {
		return fmt.Errorf("acquiring token store lock: %w", err)
	}
	if !locked {
		return errors.New("timeout acquiring token store lock")
	}
	defer func() {
		if unlockErr := fl.Unlock(); unlockErr != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to unlock token store: %v\n", unlockErr)
		}
	}()

	return fn()
}

func (f *fileStore) load() (map[string]map[string]string, error) {
	data, err := os.ReadFile(f.path)
	if err != nil {
		if os.IsNotExist(err) {
			return make(map[string]map[string]string), nil
		}
		return nil, fmt.Errorf("reading token store: %w", err)
	}
	var store map[string]map[string]string
	if err := json.Unmarshal(data, &store); err != nil {
		return nil, fmt.Errorf("parsing token store: %w", err)
	}
	return store, nil
}

// save writes the store atomically via temp file + rename so a concurrent
// reader never sees a partial JSON document.
func (f *fileStore) save(store map[string]map[string]string) error {
	data, err := json.Marshal(store)
	if err != nil {
		return fmt.Errorf("marshaling token store: %w", err)
	}
	tmp, err := os.CreateTemp(filepath.Dir(f.path), ".tokens-*.tmp")
	if err != nil {
		return fmt.Errorf("creating temp token store: %w", err)
	}
	tmpName := tmp.Name()
	defer func() { _ = os.Remove(tmpName) }()
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("writing temp token store: %w", err)
	}
	if err := tmp.Chmod(0600); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("chmod temp token store: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("closing temp token store: %w", err)
	}
	if err := os.Rename(tmpName, f.path); err != nil {
		return fmt.Errorf("renaming token store: %w", err)
	}
	return nil
}

func (f *fileStore) Get(service, user string) (string, error) {
	f.mu.Lock()
	defer f.mu.Unlock()

	var result string
	var resultErr error
	err := f.withFileLock(func() error {
		store, err := f.load()
		if err != nil {
			return err
		}
		if users, ok := store[service]; ok {
			if pass, ok := users[user]; ok {
				result = pass
				return nil
			}
		}
		resultErr = ErrNotFound
		return nil
	})
	if err != nil {
		return "", err
	}
	return result, resultErr
}

func (f *fileStore) Set(service, user, password string) error {
	f.mu.Lock()
	defer f.mu.Unlock()

	return f.withFileLock(func() error {
		store, err := f.load()
		if err != nil {
			return err
		}
		if store[service] == nil {
			store[service] = make(map[string]string)
		}
		store[service][user] = password
		return f.save(store)
	})
}

func (f *fileStore) Delete(service, user string) error {
	f.mu.Lock()
	defer f.mu.Unlock()

	var notFound bool
	err := f.withFileLock(func() error {
		store, err := f.load()
		if err != nil {
			return err
		}
		users, ok := store[service]
		if !ok {
			notFound = true
			return nil
		}
		if _, ok := users[user]; !ok {
			notFound = true
			return nil
		}
		delete(users, user)
		if len(users) == 0 {
			delete(store, service)
		}
		return f.save(store)
	})
	if err != nil {
		return err
	}
	if notFound {
		return ErrNotFound
	}
	return nil
}
