// Package userdirs resolves the per-user config directory that holds the shared
// Entire login state (contexts.json + the file token-store fallback).
//
// Vendored from the public CLI's internal/entireclient/userdirs (the test-only
// redirection branch dropped): the plugin only needs the production path so its
// login resolves the same $ENTIRE_CONFIG_DIR / ~/.config/entire that
// `entire login` writes. See ADR 20260717-entire-ci-pluggable-client.
package userdirs

import (
	"os"
	"path/filepath"
)

// Config returns the Entire config directory: $ENTIRE_CONFIG_DIR when set,
// else ~/.config/entire, falling back to a relative ".config/entire" only if
// the home directory can't be determined.
func Config() string {
	if dir := os.Getenv("ENTIRE_CONFIG_DIR"); dir != "" {
		return dir
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return filepath.Join(".config", "entire")
	}
	return filepath.Join(home, ".config", "entire")
}

